// Minimal CDP driver (Node's built-in fetch + WebSocket, no deps).
// Usage: node cdp-run.mjs <url> <screenshotPath> <waitMs> <cpuThrottleRate> [width] [height]
import { writeFileSync } from 'node:fs';

const [,, url, shotPath, waitMsArg, throttleArg, widthArg, heightArg] = process.argv;
const waitMs = Number(waitMsArg || 11000);
const throttle = Number(throttleArg || 1);
const width = Number(widthArg || 1440);
const height = Number(heightArg || 900);

const PORT = 9333;

async function main() {
  const versionRes = await fetch(`http://localhost:${PORT}/json/version`);
  await versionRes.json();

  const newTabRes = await fetch(`http://localhost:${PORT}/json/new?about:blank`, { method: 'PUT' });
  const tab = await newTabRes.json();
  const ws = new WebSocket(tab.webSocketDebuggerUrl);

  await new Promise((resolve, reject) => {
    ws.addEventListener('open', resolve, { once: true });
    ws.addEventListener('error', reject, { once: true });
  });

  let id = 0;
  const pending = new Map();
  ws.addEventListener('message', (ev) => {
    const msg = JSON.parse(ev.data);
    if (msg.id && pending.has(msg.id)) {
      const { resolve, reject } = pending.get(msg.id);
      pending.delete(msg.id);
      if (msg.error) reject(new Error(JSON.stringify(msg.error)));
      else resolve(msg.result);
    }
  });

  function send(method, params = {}) {
    const thisId = ++id;
    ws.send(JSON.stringify({ id: thisId, method, params }));
    return new Promise((resolve, reject) => pending.set(thisId, { resolve, reject }));
  }

  await send('Page.enable');
  await send('Runtime.enable');
  await send('Emulation.setDeviceMetricsOverride', {
    width, height, deviceScaleFactor: 1, mobile: false,
  });
  if (throttle !== 1) {
    await send('Emulation.setCPUThrottlingRate', { rate: throttle });
  }

  const loadFired = new Promise((resolve) => {
    function onMsg(ev) {
      const msg = JSON.parse(ev.data);
      if (msg.method === 'Page.loadEventFired') {
        ws.removeEventListener('message', onMsg);
        resolve();
      }
    }
    ws.addEventListener('message', onMsg);
  });

  await send('Page.navigate', { url });
  await loadFired;

  // real wall-clock wait so the in-page rAF sampler genuinely runs
  await new Promise((r) => setTimeout(r, waitMs));

  const evalRes = await send('Runtime.evaluate', {
    expression: 'JSON.stringify(window.__fpsResult || null)',
    returnByValue: true,
  });
  const fpsResult = JSON.parse(evalRes.result.value);

  const shot = await send('Page.captureScreenshot', { format: 'png', captureBeyondViewport: false });
  writeFileSync(shotPath, Buffer.from(shot.data, 'base64'));

  await send('Target.closeTarget', { targetId: tab.id });
  ws.close();

  console.log(JSON.stringify({ url, shotPath, throttle, width, height, fpsResult }, null, 2));
}

main().catch((e) => { console.error(e); process.exit(1); });

