// Checks console output / exceptions for a page load. No screenshot.
const [,, url, waitMs] = process.argv;
const PORT = 9333;

async function main() {
  const newTabRes = await fetch(`http://localhost:${PORT}/json/new?about:blank`, { method: 'PUT' });
  const tab = await newTabRes.json();
  const ws = new WebSocket(tab.webSocketDebuggerUrl);
  await new Promise((resolve, reject) => {
    ws.addEventListener('open', resolve, { once: true });
    ws.addEventListener('error', reject, { once: true });
  });

  let id = 0;
  const pending = new Map();
  const logs = [];
  ws.addEventListener('message', (ev) => {
    const msg = JSON.parse(ev.data);
    if (msg.id && pending.has(msg.id)) {
      const { resolve, reject } = pending.get(msg.id);
      pending.delete(msg.id);
      if (msg.error) reject(new Error(JSON.stringify(msg.error)));
      else resolve(msg.result);
    }
    if (msg.method === 'Runtime.consoleAPICalled') {
      logs.push({ type: msg.params.type, text: msg.params.args.map(a => a.value ?? a.description).join(' ') });
    }
    if (msg.method === 'Runtime.exceptionThrown') {
      logs.push({ type: 'exception', text: JSON.stringify(msg.params.exceptionDetails) });
    }
  });

  function send(method, params = {}) {
    const thisId = ++id;
    ws.send(JSON.stringify({ id: thisId, method, params }));
    return new Promise((resolve, reject) => pending.set(thisId, { resolve, reject }));
  }

  await send('Page.enable');
  await send('Runtime.enable');

  const loadFired = new Promise((resolve) => {
    function onMsg(ev) {
      const msg = JSON.parse(ev.data);
      if (msg.method === 'Page.loadEventFired') {
        ws.removeEventListener('message', onMsg);
        resolve();
      }
    }
    ws.addEventListener('message', onMsg);
  });

  await send('Page.navigate', { url });
  await loadFired;
  await new Promise((r) => setTimeout(r, Number(waitMs || 500)));

  const evalRes = await send('Runtime.evaluate', {
    expression: `JSON.stringify({
      headings: document.querySelectorAll('h1[id],h2[id],h3[id]').length,
      navLinks: document.querySelectorAll('#outline-slot a').length,
      currentEl: (document.querySelector('#outline-slot a[aria-current]')||{}).textContent || null,
      detailsOpen: document.getElementById('outline-details').open,
      transcriptHidden: document.getElementById('transcript').hidden,
      title: document.title
    })`,
    returnByValue: true,
  });

  await send('Target.closeTarget', { targetId: tab.id });
  ws.close();

  console.log('PAGE STATE:', evalRes.result.value);
  console.log('CONSOLE LOG:', JSON.stringify(logs, null, 2));
}

main().catch((e) => { console.error(e); process.exit(1); });

